    @classmethod
    def get_signal_analyzer(cls, ru):
        """
        Gets signal analyzer configuration object from given RU configuration object.
        :param ru: radio configuration object from which signal analyzer will be taken
        :type ru: RU
        :return: configuration object of signal analyzer connected to RU; None if signal analyzer is absent
        :rtype: SignalAnalyzer
        """
        return ru.signal_analyzer

    @classmethod
    def get_ru_duplex_method(cls, radio_type, fh_interface=None):
        """
        Gets certain RU duplex method for given RU type (RU name) according to records in
        taf/config/testline/info/data/ru_list.csv. If RU is not found exception is thrown.
        :param radio_type: RU name (radio_type from RU object in taf.config.testline) i.e. FXDB, AHEGA
        :type radio_type: str
        :param fh_interface: FH interface of radio, eg: CPRI/eCPRI. Some of Radio Type has multiple FH interfaces.
                            In this case radio_type and fh_interface
                            should be provided to get the correct duplex method.
        :type fh_interface: str
        :return: duplex method (FDD or TDD)
        :rtype: str
        """
        return RuListAttrs().get_ru_duplex_method(radio_type, fh_interface)

    @classmethod
    def get_ru_password(cls, username='serviceuser', **kwargs):
        """
        Gets password for given SW Line/radio_type and user from ru_credentials.csv file. One of the parameters
        'radio_sw_line' or 'radio_type' must be provided.
        :param username: user for which password is returned(rfsw or serviceuser)
        :param kwargs: additional parameters
            by_sw_line: SW Line of radio
            by_radio_type: type of radio, ignored when by_sw_line is defined.
            fh_interface: FH interface of radio eg: CPRI/eCPRI, ignored when by_sw_line is defined.
                          Some of Radio Type has multiple FH interfaces. In this case
                          by_radio_type and fh_interface should be provided to get the correct password.
        :return: password for given SW Line and user
        """
        sw_line = kwargs.get('by_sw_line')
        radio_type =  kwargs.get('by_radio_type')
        fh_interface =  kwargs.get('fh_interface')
        if sw_line and radio_type:
            logger.warning("Only one of 'by_sw_line' or 'by_radio_type' should be provided.")

        return RuListAttrs().get_ru_password(sw_line, radio_type, username, fh_interface)

    @classmethod
    def get_ru_sw_line(cls, radio_type, fh_interface=None):
        """
        Gets SW Line for given RU type (RU name) according to records in
        taf/config/testline/info/data/ru_list.csv. If RU is not found exception is thrown.
        :param radio_type: RU name (radio_type from RU object in taf.config.testline) i.e. FXDB, AHEGA
        :param fh_interface: FH interface of radio, eg: CPRI/eCPRI. Some of Radio Type has multiple FH interfaces.
                            In this case radio_type and fh_interface should be provided to get the correct SW Line.
        :type radio_type: str
        :return: SW Line of the RU
        :rtype: str
        """
        return RuListAttrs().get_ru_sw_line(radio_type, fh_interface)
